\label{lem:polar-direction-update}
Let $j\ge0$. Suppose that the polar data have $\rho_k,\zeta_k>0$
and $Z_k\succ0$ for $k=2j,2j+1,2j+2$, and that
$0<\delta_k<\pi$ and $(Z_k)_{12}>0$ for $k=2j,2j+1$.
The following statements hold for $k=2j,2j+1$:
\textup{i)} a unique $\alpha_k>0$ satisfying
$s_k=-\alpha_kH_kg_k$ exists if and only if
$r_k=\cos\delta_k+h_k\sin\delta_k$;
\textup{ii)} if the relations in part~\textup{i)} hold and $p_k^Tq_k>0$ at both stages, then
\eqref{eq:dfp-update} is equivalent to
\begin{equation}\label{eq:polar-matrix-map}
\begin{aligned}
 Z_{k+1}=R(\delta_k)^T
 \left[
 \left(I-\frac{q_kp_k^T}{p_k^Tq_k}\right)Z_k
 \left(I-\frac{p_kq_k^T}{p_k^Tq_k}\right)
 +\frac{q_kq_k^T}{p_k^Tq_k}
 \right]R(\delta_k).
\end{aligned}
\end{equation}

\label{lem:polar-endpoint-wolfe}
Let $0<\eta_1<\eta_2<1$. Suppose $0<\delta_k<\pi$, $h_k>0$,
$\rho_k,\rho_{k+1},\zeta_k,\zeta_{k+1}>0$, and
$r_k=\rho_k/\rho_{k+1}=\cos\delta_k+h_k\sin\delta_k$.
Then $g_k^Ts_k<0$, and the prescribed values and gradients satisfy the
strong Wolfe conditions if and only if(分别编号)
\begin{equation}\label{eq:polar-wolfe-ratios}
\begin{aligned}
 \frac{\rho_k^2-\rho_{k+1}^2}{-2g_k^Ts_k}
 &=\frac{r_k^2-1}{2\zeta_kh_k\sin\delta_k\,r_k}\ge\eta_1,\\
 \frac{|g_{k+1}^Ts_k|}{|g_k^Ts_k|}
 &=\frac{\zeta_{k+1}}{\zeta_k}
 \frac{|h_k\cos\delta_k-\sin\delta_k|}{h_kr_k}\le\eta_2.
\end{aligned}
\end{equation}

\label{lem:polar-limiting-cycle}
Fix $X\succ0$ with $\xi>0$, and for each $\tau>0$ set
$Z_k=S_\tau^{-1}XS_\tau^{-1}$.
If $\delta_k/\tau\to\bar\delta>0$ and
$\zeta_k,\zeta_{k+1}\to1$ as $\tau\downarrow0$, then the update
\eqref{eq:polar-matrix-map} is well defined for all sufficiently small
$\tau>0$, and $S_\tau Z_{k+1}S_\tau$ tends to the symmetric matrix
\begin{equation}\label{eq:polar-leading-map}
 X_+=\begin{pmatrix}\gamma_+&\xi_+\\\xi_+&\eta_+\end{pmatrix}
 =\begin{pmatrix}\gamma&\gamma(\bar h-\bar\delta)\\\gamma(\bar h-\bar\delta)&1+\gamma(\bar h-\bar\delta)^2\end{pmatrix}.
\end{equation}

\label{lem:polar-geometry}
For sufficiently large $j_0$, the points in \eqref{eq:polar-radii}
have accumulation set $\Gamma=\{x\in\mathbb R^2:\|x\|=1\}$ and satisfy
\begin{equation}\label{eq:polar-separation}
 \|x_m-x_k\|\ge \kappa_-\max\{\tau_{\lfloor k/2\rfloor},
                              \tau_{\lfloor m/2\rfloor}\}
 \qquad(m\ne k),
\end{equation}
where $\kappa_->0$ is independent of $j_0$.
Moreover, $\|s_k\|\asymp\tau_{\lfloor k/2\rfloor}$,
$\|g_k-x_k\|=O(\tau_{\lfloor k/2\rfloor}^{1+\beta})$, and the endpoint
data $F_k,g_k$ satisfy the strong Wolfe inequalities at every step.
The comparison constants are independent of $j_0$.

\label{lem:polar-interpolation}
Let $x_k,g_k,F_k$ be the data in Lemma~\ref{lem:polar-geometry},
with $j_0$ sufficiently large. Then there is a function
$f\in C^2(\mathbb R^2)$ whose Hessian is globally $\beta$-H\"older
continuous and which agrees with $\|x\|^2/2$ on the closed unit disk.
At every prescribed point,
\begin{equation}\label{eq:polar-endpoint-data}
f(x_k)=F_k=\frac{1}{2}\rho_k^2,\qquad
\nabla f(x_k)=g_k,\qquad \nabla^2f(x_k)=I.
\end{equation}
Writing $\Psi=f-\|x\|^2/2$, there is a constant $\kappa$ independent
of the final choice of $j_0$ such that
\begin{equation}\label{eq:polar-interpolation-bound}
\sup_{x\in\mathbb R^2}\|\nabla^2\Psi(x)\|\le \kappa\tau_0^\beta.
\end{equation}
